#!/usr/bin/env python3
"""Stage build/ + web/ into site/ — the folder that is served locally and deployed to Pages.

site/ is an artifact, not source. Every file in it is either

  * generated by scripts/build.sh / scripts/build-local.py  (engine + asset bundle),
  * copied from web/                                        (the browser UI), or
  * hand-maintained and carries no build step               (serve.py, licences, manifest).

Run with --check to verify site/ still matches its sources without writing anything. That is
the guard against the drift that once shipped placeholder stubs to production: the deployed
copies silently stopped matching web/ because no step regenerated them.
"""
from pathlib import Path
import filecmp
import shutil
import sys

ROOT = Path(__file__).resolve().parents[1]
BUILD = ROOT / "build"
WEB = ROOT / "web"
SITE = ROOT / "site"

# Engine output produced by the link step in build/.
FROM_BUILD = ["7kaa.js", "7kaa.wasm", "7kaa.data", "extras.js", "extras.data"]

# Browser sources authored in web/ and copied verbatim into the deployable folder.
FROM_WEB = [
    "siege-core.js",
    "siege-pages.js",
    "siege-hud.js",
    "siege-presentation.js",
    "siege-modern.css",
    "new-game-fields.json",
    "encyclopedia.json",
    "COPYING-Music.txt",
]

# Present in site/ by design but not produced from build/ or web/.
HAND_MAINTAINED = {
    "serve.py",
    "index.html",          # generated from build/7kaa.html, listed separately below
    "build-manifest.json",
    "COPYING.txt",
    "LICENSE-Emscripten.txt",
    "LICENSE-SDL2.txt",
}


def pairs():
    """(source, destination) pairs for every file staged from build/ or web/."""
    for name in FROM_BUILD:
        yield BUILD / name, SITE / name
    yield BUILD / "7kaa.html", SITE / "index.html"
    for name in FROM_WEB:
        yield WEB / name, SITE / name


def gallery_pairs():
    for f in sorted((WEB / "gallery").glob("*.png")):
        yield f, SITE / "gallery" / f.name


def check():
    """Return a list of human-readable problems; empty means site/ is in sync."""
    problems = []
    for src, dst in list(pairs()) + list(gallery_pairs()):
        rel_src, rel_dst = src.relative_to(ROOT), dst.relative_to(ROOT)
        if not src.exists():
            problems.append(f"missing source   {rel_src}")
        elif not dst.exists():
            problems.append(f"missing staged   {rel_dst}")
        elif not filecmp.cmp(src, dst, shallow=False):
            problems.append(f"content differs  {rel_dst}")

    expected = {p.name for p in SITE.iterdir() if p.is_file()} if SITE.is_dir() else set()
    expected -= HAND_MAINTAINED
    known = {d.name for _, d in pairs()}
    for extra in sorted(expected - known):
        problems.append(f"unexpected file  site/{extra} (not produced by build/ or web/)")

    if SITE.is_dir() and (SITE / "gallery").is_dir():
        staged = {f.name for f in (SITE / "gallery").glob("*.png")}
        authored = {f.name for f in (WEB / "gallery").glob("*.png")}
        for extra in sorted(staged - authored):
            problems.append(f"unexpected file  site/gallery/{extra}")
    return problems


def stage():
    if not (BUILD / "7kaa.html").exists():
        sys.exit("build/7kaa.html is missing — run `make build` (or `make build-local`) first")
    SITE.mkdir(exist_ok=True)
    count = 0
    for src, dst in list(pairs()) + list(gallery_pairs()):
        if not src.exists():
            sys.exit(f"missing source {src.relative_to(ROOT)}")
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
        count += 1
    print(f"staged {count} files into site/")


def main():
    if "--check" in sys.argv[1:]:
        problems = check()
        for p in problems:
            print("  " + p)
        if problems:
            sys.exit(f"\nsite/ is out of sync ({len(problems)} problem(s)) — run `make stage`")
        print(f"site/ matches build/ + web/ ({len(list(pairs())) + len(list(gallery_pairs()))} files verified)")
        return
    stage()


if __name__ == "__main__":
    main()
